(3539947, 496115, 43088, '<td valign="top">Memories of my favorite movie- "Breaking Away".</td>', 'Memories of my favorite movie- "Breaking Away".', '2007-04-11 15:22:48.000000', NULL, 1),
(3539975, 494973, 34059, '<td valign="top">I don''t know who is Dig, but anyway despite the simplicity of the picture I find it very interesting, there is a balance between the arrow being on the left and the other subjects on the right that I find very pleasant.</td>', 'I don''t know who is Dig, but anyway despite the simplicity of the picture I find it very interesting, there is a balance between the arrow being on the left and the other subjects on the right that I find very pleasant.', '2007-04-11 15:40:16.000000', NULL, 1),
(3539976, 493806, 34059, '<td valign="top">I like the narrow depth of field of this picture, but maybe a little more detail in focus would have worked too</td>', 'I like the narrow depth of field of this picture, but maybe a little more detail in focus would have worked too', '2007-04-11 15:41:03.000000', NULL, 1),
(3540057, 496003, 52403, '<td valign="top">I like this a lot, my first impression in the thumbnail was there was a mini-football style helmet (which turned out to be the pedal of course...)<br/> <br/>With the rust on the spokes, I''m thinking this was not a setup shot, which means that someone was very observant (and may have a much better memory than I do...) and used two images (not two separate pictures), that when combined give a sense of place and time that either by itself would make an interesting but not compelling picture.</td>', 'I like this a lot, my first impression in the thumbnail was there was a mini-football style helmet (which turned out to be the pedal of course...) With the rust on the spokes, I''m thinking this was not a setup shot, which means that someone was very observant (and may have a much better memory than I do...) and used two images (not two separate pictures), that when combined give a sense of place and time that either by itself would make an interesting but not compelling picture.', '2007-04-11 16:19:31.000000', NULL, 1),
(3540060, 495113, 52403, '<td valign="top">Great use of a train!</td>', 'Great use of a train!', '2007-04-11 16:20:21.000000', NULL, 1),
