(3540643, 493739, 73661, '<td valign="top">i love the desaturation and leaving only the reds. i hope this will ribbon. 10</td>', 'i love the desaturation and leaving only the reds. i hope this will ribbon. 10', '2007-04-11 19:31:31.000000', NULL, 1),
(3540707, 495872, 34059, '<td valign="top">Bumping up to 9... the more I look to this one, the more I like it!</td>', 'Bumping up to 9... the more I look to this one, the more I like it!', '2007-04-11 20:10:26.000000', NULL, 1),
(3540711, 495619, 34059, '<td valign="top">Very good execution, and I like the title so much! Good luck!</td>', 'Very good execution, and I like the title so much! Good luck!', '2007-04-11 20:12:01.000000', NULL, 1),
(3540714, 495099, 34059, '<td valign="top">Nice color, perspective and composition!</td>', 'Nice color, perspective and composition!', '2007-04-11 20:13:03.000000', NULL, 1),
(3540727, 495336, 34059, '<td valign="top">I like this very much, and only when I came back to comment I noticed that you can read all the numbers on the... how do you call them? shift wheels?<br/>I also appreciate very much the different nuances of the rust, as well as the overall composition. The only thing I don''t like is the frame, but as I don''t consider it part of the picture, this will not affect my voting. 9!</td>', 'I like this very much, and only when I came back to comment I noticed that you can read all the numbers on the... how do you call them? shift wheels?I also appreciate very much the different nuances of the rust, as well as the overall composition. The only thing I don''t like is the frame, but as I don''t consider it part of the picture, this will not affect my voting. 9!', '2007-04-11 20:16:40.000000', NULL, 1),
(3540731, 495787, 34059, '<td valign="top">One of my favorites of the challenge but maybe the perspective could have been a little more interesting. Anyway, very good job!</td>', 'One of my favorites of the challenge but maybe the perspective could have been a little more interesting. Anyway, very good job!', '2007-04-11 20:17:59.000000', NULL, 1),
(3540736, 495735, 68599, '<td valign="top">DNMC?</td>', 'DNMC?', '2007-04-11 20:19:56.000000', NULL, 1),
(3540744, 495735, 66267, '<td valign="top">Beautiful, I love the way you captured this particular bicycle in a new, inventive way. <br/> <br/> <br/> <br/> <br/> <br/> <br/> <br/>DNMC</td>', 'Beautiful, I love the way you captured this particular bicycle in a new, inventive way.        DNMC', '2007-04-11 20:22:15.000000', NULL, 1),
(3540749, 495306, 68599, '<td valign="top">what is that?</td>', 'what is that?', '2007-04-11 20:23:25.000000', NULL, 1),
(3540756, 495386, 34059, '<td valign="top">This is one of my favorite of this kind, because it looks non-staged, there is order but not of an obsessive kind. I also like the crop and the soft lighting, very nice picture!</td>', 'This is one of my favorite of this kind, because it looks non-staged, there is order but not of an obsessive kind. I also like the crop and the soft lighting, very nice picture!', '2007-04-11 20:25:54.000000', NULL, 1),
