(3544724, 495290, 53316, '<td valign="top">*blink*  Wow! You nailed this!! Good concept and flawless execution.</td>', '*blink*  Wow! You nailed this!! Good concept and flawless execution.', '2007-04-13 02:41:41.000000', NULL, 1),
