(3547329, 495676, 30982, '<td valign="top">I like the negative space.</td>', 'I like the negative space.', '2007-04-14 13:44:51.000000', NULL, 1),
(3547332, 495386, 30982, '<td valign="top">I like the diagonal composition and the reflection off the fenders.</td>', 'I like the diagonal composition and the reflection off the fenders.', '2007-04-14 13:45:44.000000', NULL, 1),
(3547335, 493600, 30982, '<td valign="top">Oooh, skinny tires hangin'' with fat tires, too.  Would like to have seen more of the bikes, but I like the idea - nice time of day from the light, too.</td>', 'Oooh, skinny tires hangin'' with fat tires, too.  Would like to have seen more of the bikes, but I like the idea - nice time of day from the light, too.', '2007-04-14 13:46:41.000000', NULL, 1),
(3547336, 495381, 30982, '<td valign="top">That baby has well and truly been stripped.  Kinda forlorn and sad...</td>', 'That baby has well and truly been stripped.  Kinda forlorn and sad...', '2007-04-14 13:47:23.000000', NULL, 1),
(3547337, 493073, 30982, '<td valign="top">Made me smile!  I like the motion - and yes, riding bikes will do that to you, regardless of age!</td>', 'Made me smile!  I like the motion - and yes, riding bikes will do that to you, regardless of age!', '2007-04-14 13:47:57.000000', NULL, 1),
(3547338, 495960, 30982, '<td valign="top">Very ambitious!  I wish them luck, good weather, and courteous drivers.</td>', 'Very ambitious!  I wish them luck, good weather, and courteous drivers.', '2007-04-14 13:48:33.000000', NULL, 1),
(3547339, 493538, 30982, '<td valign="top">I like the railing lines and the motion blur.  Imparts a nice sense of leisure.</td>', 'I like the railing lines and the motion blur.  Imparts a nice sense of leisure.', '2007-04-14 13:49:08.000000', NULL, 1),
(3547341, 496041, 30982, '<td valign="top">Very nice use of shadow.</td>', 'Very nice use of shadow.', '2007-04-14 13:49:26.000000', NULL, 1),
(3547342, 495670, 30982, '<td valign="top">Almost like a Where''s Waldo thing - nicely busy!</td>', 'Almost like a Where''s Waldo thing - nicely busy!', '2007-04-14 13:49:47.000000', NULL, 1),
(3547343, 496107, 30982, '<td valign="top">Cute!!  I never remember to dry my wheels...</td>', 'Cute!!  I never remember to dry my wheels...', '2007-04-14 13:50:56.000000', NULL, 1),
(3547344, 495636, 30982, '<td valign="top">Lovely strong silhouette.  Nice mirror on the bike, too.</td>', 'Lovely strong silhouette.  Nice mirror on the bike, too.', '2007-04-14 13:51:29.000000', NULL, 1),
(3547345, 495468, 30982, '<td valign="top">Nice road to ride, with nice scenery, too.  I''d have preferred the rider a bit less centered in the shot - maybe more to the right.</td>', 'Nice road to ride, with nice scenery, too.  I''d have preferred the rider a bit less centered in the shot - maybe more to the right.', '2007-04-14 13:52:25.000000', NULL, 1),
(3547346, 495800, 30982, '<td valign="top">Very nice!</td>', 'Very nice!', '2007-04-14 13:52:39.000000', NULL, 1),
(3547348, 495826, 30982, '<td valign="top">Nice!  I like the desat beyond the fence and keeping the color of the wall. Great action capture.</td>', 'Nice!  I like the desat beyond the fence and keeping the color of the wall. Great action capture.', '2007-04-14 13:53:38.000000', NULL, 1),
(3547349, 495974, 30982, '<td valign="top">Could use some new tape... :-)  Good composition.</td>', 'Could use some new tape... :-)  Good composition.', '2007-04-14 13:54:10.000000', NULL, 1),
(3547351, 495130, 30982, '<td valign="top">Holy cow - I guess that''s one way to keep your bike from getting stolen.</td>', 'Holy cow - I guess that''s one way to keep your bike from getting stolen.', '2007-04-14 13:54:32.000000', NULL, 1),
(3547353, 495782, 30982, '<td valign="top">Looks to be a good day to ride, even if it is a tad windy.</td>', 'Looks to be a good day to ride, even if it is a tad windy.', '2007-04-14 13:55:35.000000', NULL, 1),
(3547364, 495740, 30982, '<td valign="top">I like the almost abstract nature of this - very much like it in B&amp;W, too.</td>', 'I like the almost abstract nature of this - very much like it in B&W, too.', '2007-04-14 14:08:02.000000', NULL, 1),
(3547366, 496025, 30982, '<td valign="top">Either than''s new, or it''s had a very very good cleaning!  Nice image - I like the light and the shadow.</td>', 'Either than''s new, or it''s had a very very good cleaning!  Nice image - I like the light and the shadow.', '2007-04-14 14:08:44.000000', NULL, 1),
(3547377, 493801, 30982, '<td valign="top">Very interesting!  I''m assuming it''s under water.  End result is quite good, in my opinion.</td>', 'Very interesting!  I''m assuming it''s under water.  End result is quite good, in my opinion.', '2007-04-14 14:19:50.000000', NULL, 1),
(3547379, 495854, 30982, '<td valign="top">Very nice find!</td>', 'Very nice find!', '2007-04-14 14:20:23.000000', NULL, 1),
(3547380, 495032, 30982, '<td valign="top">I like the isolation of the cyclist and the horizontal lines of the crosswalk emphasize that nicely.</td>', 'I like the isolation of the cyclist and the horizontal lines of the crosswalk emphasize that nicely.', '2007-04-14 14:21:00.000000', NULL, 1),
(3547382, 495979, 30982, '<td valign="top">As long as the frame is solid, you can!  Love the expression on the surgeon.</td>', 'As long as the frame is solid, you can!  Love the expression on the surgeon.', '2007-04-14 14:21:41.000000', NULL, 1),
