(3547384, 496132, 30982, '<td valign="top">What an interesting place!  I''ll check back to see where this is.</td>', 'What an interesting place!  I''ll check back to see where this is.', '2007-04-14 14:22:16.000000', NULL, 1),
(3547387, 495110, 30982, '<td valign="top">I quite like the minimalistic nature of this.  Nicely done.</td>', 'I quite like the minimalistic nature of this.  Nicely done.', '2007-04-14 14:23:49.000000', NULL, 1),
(3547389, 495710, 30982, '<td valign="top">I like the comparitive sizes.</td>', 'I like the comparitive sizes.', '2007-04-14 14:24:54.000000', NULL, 1),
