(3547927, 496130, 60915, '<td valign="top">Beautiful rage of tones here, well done!</td>', 'Beautiful rage of tones here, well done!', '2007-04-14 20:34:34.000000', NULL, 1),
(3547947, 495576, 60915, '<td valign="top">I really like this shot, love the contrast between the lady and the bike. The office chair is so out of place with the rest of the scene. Could maybe benefit from a little sharpening. Well done! :)</td>', 'I really like this shot, love the contrast between the lady and the bike. The office chair is so out of place with the rest of the scene. Could maybe benefit from a little sharpening. Well done! :)', '2007-04-14 20:42:06.000000', NULL, 1),
(3547954, 492801, 60915, '<td valign="top">Love the way this is blurred, it really give a sense of rough cobble stones. Feels like my eye balls a rattling around in my head! :) Nice job!</td>', 'Love the way this is blurred, it really give a sense of rough cobble stones. Feels like my eye balls a rattling around in my head! :) Nice job!', '2007-04-14 20:44:51.000000', NULL, 1),
