(3549273, 494967, 76198, '<td valign="top">Really nice. Great color, great expression on the rider.</td>', 'Really nice. Great color, great expression on the rider.', '2007-04-15 13:31:30.000000', NULL, 1),
(3549282, 495735, 76198, '<td valign="top">Had to look a long time to find the bicycles... So nice shot but DNMC.</td>', 'Had to look a long time to find the bicycles... So nice shot but DNMC.', '2007-04-15 13:33:39.000000', NULL, 1),
(3549290, 495032, 76198, '<td valign="top">Great idea, great composition... with better focus on the bike and higher contrast this would score very high from me. As is - pretty high.</td>', 'Great idea, great composition... with better focus on the bike and higher contrast this would score very high from me. As is - pretty high.', '2007-04-15 13:37:54.000000', NULL, 1),
(3549295, 493060, 76198, '<td valign="top">Wonderful. 9.</td>', 'Wonderful. 9.', '2007-04-15 13:41:02.000000', NULL, 1),
(3549297, 496119, 76198, '<td valign="top">Oof, bad aliasing in the peg... Not your fault, though; I assume it''d be better at a larger size. So that aside, really nice picture.</td>', 'Oof, bad aliasing in the peg... Not your fault, though; I assume it''d be better at a larger size. So that aside, really nice picture.', '2007-04-15 13:43:34.000000', NULL, 1),
(3549298, 495784, 76198, '<td valign="top">Like the grungy bike. Wish the sky were a little more exposed.</td>', 'Like the grungy bike. Wish the sky were a little more exposed.', '2007-04-15 13:44:23.000000', NULL, 1),
(3549300, 495826, 76198, '<td valign="top">Great capture of the moment; I like the desat. Good work. 9.</td>', 'Great capture of the moment; I like the desat. Good work. 9.', '2007-04-15 13:45:48.000000', NULL, 1),
(3549302, 495957, 76198, '<td valign="top">Nothing to see, really.</td>', 'Nothing to see, really.', '2007-04-15 13:46:06.000000', NULL, 1),
(3549303, 493606, 76198, '<td valign="top">Great colors, great feel. It''s like a snapshot you find in a gutter; you''ve got just a piece of a story. Wonderful. 9.</td>', 'Great colors, great feel. It''s like a snapshot you find in a gutter; you''ve got just a piece of a story. Wonderful. 9.', '2007-04-15 13:47:55.000000', NULL, 1),
(3549305, 495692, 76198, '<td valign="top">Perhaps nitpicky, but I''d put the negative space in front of her; the direction of the bike leads your eye out of the picture to the left. Otherwise a great shot, very cute.</td>', 'Perhaps nitpicky, but I''d put the negative space in front of her; the direction of the bike leads your eye out of the picture to the left. Otherwise a great shot, very cute.', '2007-04-15 13:49:18.000000', NULL, 1),
(3549308, 494977, 76198, '<td valign="top">Mmm, contrast. I like it.</td>', 'Mmm, contrast. I like it.', '2007-04-15 13:49:46.000000', NULL, 1),
(3549312, 495246, 23484, '<td valign="top">I like the sepia tone to this. It fits very well.</td>', 'I like the sepia tone to this. It fits very well.', '2007-04-15 13:53:36.000000', NULL, 1),
(3549314, 496087, 76198, '<td valign="top">Great shot, great colors. Looks very 1960''s/techicolor. Now I want a bright yellow house! I think you should take it again with a vintage bike, then it''d be perfect.</td>', 'Great shot, great colors. Looks very 1960''s/techicolor. Now I want a bright yellow house! I think you should take it again with a vintage bike, then it''d be perfect.', '2007-04-15 13:57:06.000000', NULL, 1),
(3549316, 495468, 76198, '<td valign="top">subject too centered, colors oversaturated.</td>', 'subject too centered, colors oversaturated.', '2007-04-15 13:57:44.000000', NULL, 1),
(3549318, 495854, 76198, '<td valign="top">That''s great. Took me a long time to decide if the bike was real or not. But... Is this just a photo of a nice trompe l''oi? That is, does the act of photographing it add to the art? Not sure.</td>', 'That''s great. Took me a long time to decide if the bike was real or not. But... Is this just a photo of a nice trompe l''oi? That is, does the act of photographing it add to the art? Not sure.', '2007-04-15 14:00:45.000000', NULL, 1),
(3549320, 495130, 76198, '<td valign="top">Nice shot. Bike''s hard to see, but the building lines lead you there; it clearly becomes the subject of the shot by virtue of the composition. I like it.</td>', 'Nice shot. Bike''s hard to see, but the building lines lead you there; it clearly becomes the subject of the shot by virtue of the composition. I like it.', '2007-04-15 14:02:00.000000', NULL, 1),
(3549323, 495178, 76198, '<td valign="top">Too little!</td>', 'Too little!', '2007-04-15 14:02:34.000000', NULL, 1),
