(3549975, 495178, 59740, '<td valign="top">Good potential but there is too much. It would have been more interesting if you had cropped to the axle and spokes.</td>', 'Good potential but there is too much. It would have been more interesting if you had cropped to the axle and spokes.', '2007-04-15 21:00:48.000000', NULL, 1),
(3549981, 495784, 59740, '<td valign="top">Good idea but a large part of the photo is filled with uninteresting background.</td>', 'Good idea but a large part of the photo is filled with uninteresting background.', '2007-04-15 21:02:05.000000', NULL, 1),
(3549985, 493291, 59740, '<td valign="top">Good idea but not sharp enough for a "captured moment" shot and too sharp for a "motion blur" shot. A little camera panning would have helped.</td>', 'Good idea but not sharp enough for a "captured moment" shot and too sharp for a "motion blur" shot. A little camera panning would have helped.', '2007-04-15 21:03:07.000000', NULL, 1),
(3549986, 495787, 59740, '<td valign="top">Good photo. Nice exposure and good repeating patterns. I would like to see a different angle with the background less distracting.</td>', 'Good photo. Nice exposure and good repeating patterns. I would like to see a different angle with the background less distracting.', '2007-04-15 21:04:07.000000', NULL, 1),
(3549989, 493747, 59740, '<td valign="top">Too busy.</td>', 'Too busy.', '2007-04-15 21:04:28.000000', NULL, 1),
(3549993, 496047, 59740, '<td valign="top">This is a very difficult shot with a huge range of brightness. The shadows have no detail and the highlights are blown out. Nice try.</td>', 'This is a very difficult shot with a huge range of brightness. The shadows have no detail and the highlights are blown out. Nice try.', '2007-04-15 21:05:32.000000', NULL, 1),
(3549996, 493248, 59740, '<td valign="top">The girl, not the bike is the center of attention. Great for a glamour shot but not a bike shot.</td>', 'The girl, not the bike is the center of attention. Great for a glamour shot but not a bike shot.', '2007-04-15 21:06:31.000000', NULL, 1),
(3549997, 492801, 59740, '<td valign="top">There is not enough of the bike or the person in the frame. The street is blurred but it should be sharp while the bike is blurred.</td>', 'There is not enough of the bike or the person in the frame. The street is blurred but it should be sharp while the bike is blurred.', '2007-04-15 21:07:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3550000, 495130, 59740, '<td valign="top">The bike is too small. I almost missed it altogether.</td>', 'The bike is too small. I almost missed it altogether.', '2007-04-15 21:08:15.000000', NULL, 1),
(3550002, 495635, 59740, '<td valign="top">Great shot. The only improvement might be a little motion blur. It is sharp, tight, and well exposed. I gave it an 8.</td>', 'Great shot. The only improvement might be a little motion blur. It is sharp, tight, and well exposed. I gave it an 8.', '2007-04-15 21:09:16.000000', NULL, 1),
(3550004, 495290, 59740, '<td valign="top">A little confusing. I''m not sure what''s going on.</td>', 'A little confusing. I''m not sure what''s going on.', '2007-04-15 21:09:58.000000', NULL, 1),
(3550007, 495828, 59740, '<td valign="top">This is not a bicycle!!!</td>', 'This is not a bicycle!!!', '2007-04-15 21:10:56.000000', NULL, 1),
(3550010, 494996, 59740, '<td valign="top">Good shot but I think it could use a little more punch. It isn''t light enough to be "high key".</td>', 'Good shot but I think it could use a little more punch. It isn''t light enough to be "high key".', '2007-04-15 21:12:07.000000', NULL, 1),
(3550013, 495665, 59740, '<td valign="top">Good idea but as a cyclist myself it looks posed. When you fall down, your first impulse (unfortunately because you can break a wrist) is to reach out to break your fall. I would be interested to know if this is a real fall.</td>', 'Good idea but as a cyclist myself it looks posed. When you fall down, your first impulse (unfortunately because you can break a wrist) is to reach out to break your fall. I would be interested to know if this is a real fall.', '2007-04-15 21:14:05.000000', NULL, 1),
(3550017, 495669, 59740, '<td valign="top">A little overexposed. Not enough contrast.</td>', 'A little overexposed. Not enough contrast.', '2007-04-15 21:14:49.000000', NULL, 1),
(3550019, 496003, 59740, '<td valign="top">Excellent. I hope that never happens to my bike.</td>', 'Excellent. I hope that never happens to my bike.', '2007-04-15 21:15:31.000000', NULL, 1),
(3550022, 495843, 59740, '<td valign="top">Not enough of the bike in the image.</td>', 'Not enough of the bike in the image.', '2007-04-15 21:16:29.000000', NULL, 1),
(3550026, 493600, 59740, '<td valign="top">Background too distracting.</td>', 'Background too distracting.', '2007-04-15 21:17:06.000000', NULL, 1),
(3550031, 496064, 59740, '<td valign="top">I think this would have been great with the feet in the shot. I like the road motion blur.</td>', 'I think this would have been great with the feet in the shot. I like the road motion blur.', '2007-04-15 21:18:12.000000', NULL, 1),
(3550032, 495317, 59740, '<td valign="top">Nice.</td>', 'Nice.', '2007-04-15 21:18:30.000000', NULL, 1),
(3550034, 495680, 59740, '<td valign="top">Good idea. I would have put the flat tire in the foreground. The blurred deck boards are distracting.</td>', 'Good idea. I would have put the flat tire in the foreground. The blurred deck boards are distracting.', '2007-04-15 21:19:31.000000', NULL, 1),
(3550035, 495897, 59740, '<td valign="top">This is a not too good depiction of someone else''s art.</td>', 'This is a not too good depiction of someone else''s art.', '2007-04-15 21:20:16.000000', NULL, 1),
(3550037, 495819, 59740, '<td valign="top">I like the shadows and the lonely bike. Could be sharper.</td>', 'I like the shadows and the lonely bike. Could be sharper.', '2007-04-15 21:21:02.000000', NULL, 1),
(3550042, 495632, 59740, '<td valign="top">Too much tonal range in the scene. The bike shadows are lost and the sky is blown out.</td>', 'Too much tonal range in the scene. The bike shadows are lost and the sky is blown out.', '2007-04-15 21:21:53.000000', NULL, 1),
(3550043, 495693, 59740, '<td valign="top">Almost great. It would have been a lot better if you could see the second riders head. I love the motion blur.</td>', 'Almost great. It would have been a lot better if you could see the second riders head. I love the motion blur.', '2007-04-15 21:22:42.000000', NULL, 1),
(3550047, 493073, 59740, '<td valign="top">Terrific. (But I''m a sucker for little kids). The motion blur and the child''s concentration are great. If only the child and bike were a little sharper.</td>', 'Terrific. (But I''m a sucker for little kids). The motion blur and the child''s concentration are great. If only the child and bike were a little sharper.', '2007-04-15 21:24:11.000000', NULL, 1),
(3550053, 495785, 59740, '<td valign="top">Great shot. Excellent repeating pattern, good exposure and sharp. I might have cropped out the tree. Try cropping out half the bikes and you will eliminate some of the uninteresting sky.</td>', 'Great shot. Excellent repeating pattern, good exposure and sharp. I might have cropped out the tree. Try cropping out half the bikes and you will eliminate some of the uninteresting sky.', '2007-04-15 21:27:05.000000', NULL, 1),
(3550056, 495035, 59740, '<td valign="top">I love it. Very mysterious.</td>', 'I love it. Very mysterious.', '2007-04-15 21:27:59.000000', NULL, 1),
(3550059, 494862, 59740, '<td valign="top">Good composition and exposure but could be a little sharper.</td>', 'Good composition and exposure but could be a little sharper.', '2007-04-15 21:29:03.000000', NULL, 1),
(3550061, 495735, 59740, '<td valign="top">The bikes are too far away. I like the shot but wouldn''t have entered it in this category. I would crop off the bottom.</td>', 'The bikes are too far away. I like the shot but wouldn''t have entered it in this category. I would crop off the bottom.', '2007-04-15 21:30:23.000000', NULL, 1),
(3550062, 495800, 59740, '<td valign="top">Great photo. I can feel the motion. (I''m a cyclist). I would have liked it even better with hands in the picture. I think I''ll try this shot myself with the camera against my chest and the self timer. I gave it a 9.</td>', 'Great photo. I can feel the motion. (I''m a cyclist). I would have liked it even better with hands in the picture. I think I''ll try this shot myself with the camera against my chest and the self timer. I gave it a 9.', '2007-04-15 21:32:30.000000', NULL, 1),
(3550079, 493248, 37524, '<td valign="top">I like the Idea, but I think to make it a notch better, I would have liked to see all her leg, and all of the bike.</td>', 'I like the Idea, but I think to make it a notch better, I would have liked to see all her leg, and all of the bike.', '2007-04-15 21:42:18.000000', NULL, 1),
(3550296, 495386, 70514, '<td valign="top">Nice composition and clarity.</td>', 'Nice composition and clarity.', '2007-04-15 23:35:06.000000', NULL, 1),
(3550305, 495059, 70514, '<td valign="top">I wish I could see more of the tree, but I like the idea.  Very funny.</td>', 'I wish I could see more of the tree, but I like the idea.  Very funny.', '2007-04-15 23:37:31.000000', NULL, 1),
